		DryRun:     true,
		LockFile:   lockFile,
		StateFile:  stateFile,
		RepoDir:    repoDir,
		StagingDir: stagingDir,
	}

	// Acquire lock manually first.
	r1 := NewReconciler(cfg, WithGitOperations(gitOps))
	require.NoError(t, r1.acquireLock())
