	})

	t.Run("passes services and duration", func(t *testing.T) {
		tmpDir := t.TempDir()
		stateFile := filepath.Join(tmpDir, "state.json")

		alerter := &mockAlertSender{}
		cfg := &Config{StateFile: stateFile, OnFailure: true}
		r := NewReconciler(cfg, WithAlerter(alerter))
		r.lastCommit = "abc123"
